# coding=utf-8
"""Preflight checks for Tailect ASR local models."""

from __future__ import annotations

import argparse
import os
import sys
import time
from pathlib import Path
from typing import Iterable, Optional

import torch

from tailect_asr.cli.api_v1 import (
    ALIGNER_REQUIRED_FILES,
    ASR_REQUIRED_FILES,
    TailectApiService,
    build_runtime_config,
    canonical_model_alias,
    find_tailect_root,
    prepare_local_diarization_model,
    run_startup_checks,
)


def _exists(path: Path, label: str) -> None:
    if not path.exists():
        raise FileNotFoundError(f"missing {label}: {path}")
    print(f"[preflight] ok {label}: {path}")


def _check_model_layout(root: Path, model_alias: str, aligner: Path) -> None:
    asr_dir = root / "models" / "ASR" / model_alias
    _exists(asr_dir, "ASR directory")
    for name in ASR_REQUIRED_FILES:
        _exists(asr_dir / name, f"ASR file {name}")

    _exists(aligner, "ForcedAligner directory")
    for name in ALIGNER_REQUIRED_FILES:
        _exists(aligner / name, f"ForcedAligner file {name}")


def build_arg_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="tailect-asr-preflight")
    parser.add_argument("--model", default="Taizhou", help="Model alias: Taizhou or Tiantai.")
    parser.add_argument("--root", default=None, help="Tailect_ASR_Win10 root directory.")
    parser.add_argument("--audio", default=None, help="Optional audio file for smoke test.")
    parser.add_argument("--dtype", default="bf16", choices=["bf16", "bfloat16", "fp16", "float16", "fp32", "float32"])
    parser.add_argument("--device-map", default="cuda:0")
    parser.add_argument("--max-inference-batch-size", type=int, default=4)
    parser.add_argument("--max-new-tokens", type=int, default=128)
    parser.add_argument("--diarize", dest="diarize", default=True, action=argparse.BooleanOptionalAction)
    parser.add_argument("--allow-diarization-fallback", action="store_true")
    parser.add_argument("--server", default="uvicorn", choices=["uvicorn", "flask"])
    parser.add_argument("--max-upload-mb", type=int, default=512)
    parser.add_argument("--queue-timeout-sec", type=float, default=600.0)
    parser.add_argument("--rate-limit-per-minute", type=int, default=60)
    parser.add_argument("--skip-transcribe", action="store_true")
    parser.add_argument("--skip-diarize-infer", action="store_true")
    return parser


def main(argv: Optional[Iterable[str]] = None) -> int:
    parser = build_arg_parser()
    args = parser.parse_args(argv)
    root = Path(args.root or find_tailect_root()).expanduser().resolve()
    model_alias = canonical_model_alias(args.model)
    aligner = root / "models" / "ForcedAligner"

    print(f"[preflight] root={root}")
    print(f"[preflight] model={model_alias}")
    print(f"[preflight] python={sys.executable}")
    print(f"[preflight] torch={getattr(torch, '__version__', 'unknown')}")
    print(f"[preflight] cuda_available={torch.cuda.is_available()}")
    if torch.cuda.is_available():
        print(f"[preflight] cuda_device={torch.cuda.get_device_name(0)}")

    _check_model_layout(root, model_alias, aligner)

    service_args = argparse.Namespace(
        model=model_alias,
        root=str(root),
        asr_checkpoint=None,
        aligner_checkpoint=None,
        host="127.0.0.1",
        port=8885,
        server=args.server,
        dtype=args.dtype,
        device_map=args.device_map,
        max_inference_batch_size=args.max_inference_batch_size,
        max_new_tokens=args.max_new_tokens,
        diarize=args.diarize,
        diarization_fallback=args.allow_diarization_fallback,
        max_chars=40,
        split_by_punctuation=True,
        max_upload_mb=args.max_upload_mb,
        queue_timeout_sec=args.queue_timeout_sec,
        startup_check=True,
        api_key=None,
        api_key_env="TAILECT_API_KEY",
        rate_limit_per_minute=args.rate_limit_per_minute,
        upload_dir=None,
        log_dir=None,
    )
    cfg = build_runtime_config(service_args)
    run_startup_checks(cfg)

    if cfg.diarize:
        sd_dir = prepare_local_diarization_model(cfg.root_dir)
        print(f"[preflight] ok diarization local config: {sd_dir}")

    start = time.time()
    service = TailectApiService(cfg)
    service.load()
    print(f"[preflight] ok model load elapsed_sec={round(time.time() - start, 2)}")

    audio = Path(args.audio).expanduser().resolve() if args.audio else root.parent / "prompt材料" / "bian.wav"
    if not args.skip_transcribe and audio.exists():
        start = time.time()
        language, rows, text = service.transcribe_file(
            audio_path=audio,
            language=None,
            diarize=bool(cfg.diarize and not args.skip_diarize_infer),
            max_chars=40,
            split_by_punctuation=True,
        )
        print(f"[preflight] ok transcribe elapsed_sec={round(time.time() - start, 2)}")
        print(f"[preflight] language={language}")
        print(f"[preflight] text_preview={text[:120]}")
        print(f"[preflight] row_count={len(rows)}")
        if rows:
            print(f"[preflight] first_row={rows[0]}")
    elif not args.skip_transcribe:
        print(f"[preflight] skip transcribe: audio not found: {audio}")

    print("[preflight] all checks passed")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
